with (P/'primary-context-sidecar.csv').open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=list(flat[0]));w.writeheader();w.writerows(flat)
# Audit actual two supervised PPIKB inputs used by the100 fixed manual models. No model loading.
